        if (Name is not null) parameters.Add(new KeyValuePair<string, string>("name", Name));
        if (OrderBy is not null) parameters.Add(new KeyValuePair<string, string>("order_by", OrderBy.Value.Value));
        if (OrganizationId is not null) parameters.Add(new KeyValuePair<string, string>("organization_id", OrganizationId));
